    /// True but under `-RCDevDerivedHidden YES` in a build with the dev tools.
    static var derivedDisplay: Bool {
        #if FRAMEJOB_DEV_TOOLS
        return !UserDefaults.standard.bool(forKey: derivedHiddenKey)
        #else
        return true
