//! The persisted format: the version number, the reader's caps, and the
//! read-any-version / write-current pair behind `project.json` in a
//! `.framejob` package (spec §5.6).
//!
//! The rule this module exists to enforce: **the reader accepts every prior
//! version, and the writer enforces the reader's caps**, so every file this
//! build produces can be read back by this build. Any change to the
//! persisted schema bumps [`RC_FORMAT_VERSION`] here AND the `#define` in
//! `core/include/framejob_core.h`, and adds a migration step in [`read`].

use serde_json::{json, Value};

use crate::model::{Canvas, Project};

/// Bumped by any change to the persisted project schema. Mirrored by
/// `RC_FORMAT_VERSION` in the C header.
/// What each version added is [`crate::format_history`].
pub const RC_FORMAT_VERSION: u32 = 43;

/// The number the grading branch's builds wrote (spec §11 GR-9); read as version 15.
pub const GRADING_BRANCH_VERSION: u32 = 1015;

/// Reader caps, mirrored by the `RC_MAX_*` defines in the C header. They
/// exist so a corrupt or generated file cannot make the app allocate
/// without bound, and they are generous: 4096 clips is far past what the
/// timeline UI stays usable at.
pub const MAX_CLIPS: usize = 4096;
pub const MAX_TRACKS: usize = 64;
pub const MAX_MARKERS: usize = 1024;
pub const MAX_MEDIA: usize = 1024;

/// The largest `.cube` file `cube.rs` reads (spec §11 GR-8): 32 MiB, which
/// holds a 65³ table four times over at the precision tools write, and keeps
/// a stray file named `.cube` from being read whole. Mirrored by
/// `RC_CUBE_MAX_BYTES` in the C header; the app reads at most one byte more,
/// so a larger file is refused by the core's own sentence.
pub const RC_CUBE_MAX_BYTES: usize = 33_554_432;

/// How many levels of nest may sit inside one another. A cap on the WALK,
/// not on taste: every evaluation of a nested layer recurses once per
/// level, and eight levels is already past anything an editor does on
/// purpose. `Project::validate` refuses a deeper file, and it refuses a
/// nest that reaches itself at any depth, so no walk downstream needs a
/// visited set of its own.
pub const MAX_NEST_DEPTH: u32 = 8;

/// The caps check both sides share: [`Project::validate`] runs it on read,
/// [`write`] runs it before serializing. One implementation, so the writer
/// can never produce a file the reader rejects.
///
/// Nested tracks and clips count toward the same two caps as the
/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    if p.markers.len() > MAX_MARKERS {
        return Err(format!(
            "too many markers: {} (max {})",
            p.markers.len(),
            MAX_MARKERS
        ));
    }
    if p.media.len() > MAX_MEDIA {
        return Err(format!(
            "too many media: {} (max {})",
            p.media.len(),
            MAX_MEDIA
        ));

import AppKit

/// The panel SHOWN: `show()`, the one-second timer that keeps the Record Into
/// rows current while it is up, `setNote` and the refit that keeps the card on
/// its screen — `RecorderPanelController.swift`'s ninth file. A pure move out
/// of the base file, which stood at 399 lines against the 400-line cap a
/// Camera source would have grown: camera recording's CR1-0, paid first and
/// alone. Its `// MARK: - Showing` came here whole, bodies untouched;
/// `armSyncTimer` stays private, since its one caller, `show()`, moved with it.
extension RecorderPanelController {

    // MARK: - Showing

    /// Beeps and shows nothing while a recording has the panel hidden (the
    /// type doc): the welcome window's button is the caller that would
    /// otherwise un-hide it into the recording. Shown while idle, a prepared
    /// capture that failed (or a build that threw) is let go first, so the
    /// preview's sync tries again (spec §11 CAM-7 (5)). The device observers
    /// are added before that sync, which applies a change made while the
    /// panel was closed (CAM-8 (1)).
    func show() {
        guard !hiddenForRecording else {
            NSSound.beep()
            return
        }
        panelClosing = false
        if phase == .idle {
            rebuildSources()
            rebuildMicrophones()
            rebuildCameras()
            restoreChoices()
            if recorder.state == .idle, previewFailure != nil { recorder.discardPreparedCamera() }
        }
        rebuildDestinations()
        refreshSizeNote()
        fitWindowToContent()
        floatAgain()
        if NSApp.isActive {
            showWindow(nil)
            window?.makeKeyAndOrderFront(nil)
        } else {
            window?.orderFrontRegardless()
        }
        armSyncTimer()
        observeDevices()
        syncCameraPreview()
    }

    /// One second, while the panel is up: the Record Into rows follow the
    /// documents that open and close and the one in front — while idle,
    /// which `rebuildDestinations` itself decides — and the camera preview
    /// steps again (CAM-7 (5)).
    private func armSyncTimer() {
        guard syncTimer == nil else { return }
        syncTimer = Timer.scheduledTimer(withTimeInterval: 1, repeats: true) { [weak self] timer in
            guard let self else {
                timer.invalidate()
                return
            }
            guard self.window?.isVisible == true else { return }
                "New Project from Range…",
                #selector(EditorViewController.newProjectFromRange(_:))))
        // The timeline's 9:16, 4:5 or 1:1 version, opened as a copy or made in place (spec §11
        // VR-39); no key.
        menu.addItem(
            item(
                "Make Vertical Version…",
                #selector(EditorViewController.showVerticalVersionSheet(_:))))
        menu.addItem(item("Open…", #selector(NSDocumentController.openDocument(_:)), "o"))

        // AppKit auto-populates a submenu whose sole item's action is
        // clearRecentDocuments: as the Open Recent menu.
        let openRecent = NSMenu(title: "Open Recent")
        openRecent.addItem(
            item("Clear Menu", #selector(NSDocumentController.clearRecentDocuments(_:))))
        let openRecentItem = NSMenuItem(title: "Open Recent", action: nil, keyEquivalent: "")
        openRecentItem.submenu = openRecent
        menu.addItem(openRecentItem)

